    {
      "name": "price_rank_mismatch",
      "description": "Blocks booking or changing to an itinerary that is more expensive than the user's requested rank (cheapest or second cheapest) among all options present in the search history for the same one-way route, date, and cabin.",
      "clause": "Consistency rule: when the user asks for the cheapest or second cheapest fare, the selected itinerary must match that price rank across direct and one-stop options.",
      "code": "def check(call, history):
    if call.get('name') not in ('book_reservation', 'update_reservation_flights'):
        return False
    recent = []
    for msg in reversed(history):
        if msg.get('role') == 'user':
            recent.append(str(msg.get('content', '')).lower())
            if len(recent) >= 6:
                break
    text = ' '.join(recent)
    if 'second cheapest' in text:
        rank = 1
    elif 'cheapest' in text and 'second' not in text:
        rank = 0
    else:
        return False
    args = call.get('arguments', {})
    cabin = args.get('cabin')
    if not cabin:
        return False
    flights = args.get('flights')
    if not isinstance(flights, list) or not flights:
        return False
    dates = set()
    for f in flights:
        if isinstance(f, dict) and f.get('date'):
            dates.add(f['date'])
    if len(dates) != 1:
        return False
    date = list(dates)[0]
    fmap = {}
    def walk(x):
        if isinstance(x, dict):
            fn = x.get('flight_number')
            if fn:
                prices = x.get('prices') or {}
                price = prices.get(cabin) if isinstance(prices, dict) else None
                if price is None:
                    price = x.get(cabin + '_price')
                if price is not None:
                    fmap[fn] = {'origin': x.get('origin'), 'destination': x.get('destination'), 'price': price}
            for v in x.values():
                walk(v)
        elif isinstance(x, list):
            for v in x:
                walk(v)
    for msg in history:
        if msg.get('role') == 'tool':
            walk(msg.get('result'))
    origin = args.get('origin')
    destination = args.get('destination')
    if not origin or not destination:
        first_fn = flights[0].get('flight_number') if isinstance(flights[0], dict) else None
        last_fn = flights[-1].get('flight_number') if isinstance(flights[-1], dict) else None
        if first_fn in fmap:
            origin = fmap[first_fn]['origin']
        if last_fn in fmap:
            destination = fmap[last_fn]['destination']
    if not origin or not destination:
        return False
    selected = 0
    for f in flights:
        if not isinstance(f, dict):
            return False
        fn = f.get('flight_number')
        if fn not in fmap or fmap[fn]['price'] is None:
            return False
        selected += fmap[fn]['price']
    calls = []
    for msg in history:
        if msg.get('role') == 'assistant' and msg.get('tool_calls'):
            for tc in msg['tool_calls']:
                calls.append(tc)
    results = [msg.get('result') for msg in history if msg.get('role') == 'tool']
    candidates = []
    for tc, res in zip(calls, results):
        tname = tc.get('name')
        targs = tc.get('arguments', {})
        if targs.get('origin') != origin or targs.get('destination') != destination:
            continue
        if targs.get('date') != date:
            continue
        if tname == 'search_direct_flight' and isinstance(res, list):
            for item in res:
                if isinstance(item, dict):
                    prices = item.get('prices') or {}
                    p = prices.get(cabin) if isinstance(prices, dict) else None
                    if p is None:
                        p = item.get(cabin + '_price')
                    if p is not None:
                        candidates.append(p)
        elif tname == 'search_onestop_flight' and isinstance(res, list):
            for itinerary in res:
                if isinstance(itinerary, list):
                    total = 0
                    good = True
                    for leg in itinerary:
                        if not isinstance(leg, dict):
                            good = False
                            break
                        prices = leg.get('prices') or {}
                        p = prices.get(cabin) if isinstance(prices, dict) else None
                        if p is None:
                            p = leg.get(cabin + '_price')
                        if p is None:
                            good = False
                            break
                        total += p
                    if good:
                        candidates.append(total)
    if not candidates:
        return False
    candidates.sort()
    if rank >= len(candidates):
        return False
    return selected > candidates[rank]"
