    {
      "name": "update_flights_wrong_destination",
      "description": "Blocks an update to flights when the user has positively requested a different destination airport than the one used in the proposed itinerary and the requested airport is absent from the update.",
      "clause": "Consistency rule: a modification must keep the same origin and destination. If the user wants a different destination, do not call update_reservation_flights with the old destination; use cancel-and-rebook when eligible.",
      "code": "def check(call, history):
    if call.get('name') != 'update_reservation_flights':
        return False
    args = call.get('arguments', {})
    rid = args.get('reservation_id')
    if not rid:
        return False
    res = None
    for msg in reversed(history):
        if msg.get('role') == 'tool':
            r = msg.get('result')
            if isinstance(r, dict) and r.get('reservation_id') == rid:
                res = r
                break
    if not res:
        return False
    orig_org = res.get('origin')
    orig_dst = res.get('destination')
    if not orig_dst:
        return False
    texts = []
    for msg in reversed(history):
        if msg.get('role') == 'user':
            texts.append(str(msg.get('content', '')))
            if len(texts) >= 5:
                break
    text = ' '.join(texts)
    import re
    codes = set()
    for m in re.finditer(r'\b(?:to|want|need|prefer|go to|instead of)\s+([A-Z]{3})\b', text):
        codes.add(m.group(1))
    for m in re.finditer(r'\b([A-Z]{3})\s+instead of\b', text):
        codes.add(m.group(1))
    for m in re.finditer(r'\b([A-Z]{3})\s+is really\b', text):
        codes.add(m.group(1))
    if not codes:
        return False
    fmap = {}
    def walk(x):
        if isinstance(x, dict):
            fn = x.get('flight_number')
            if fn:
                fmap[fn] = (x.get('origin'), x.get('destination'))
            for v in x.values():
                walk(v)
        elif isinstance(x, list):
            for v in x:
                walk(v)
    for msg in history:
        if msg.get('role') == 'tool':
            walk(msg.get('result'))
    call_dests = set()
    for f in args.get('flights', []):
        if isinstance(f, dict):
            fn = f.get('flight_number')
            if fn in fmap:
                call_dests.add(fmap[fn][1])
    for c in codes:
        if c != orig_dst and c != orig_org and c not in call_dests:
            return True
    return False"
