    for p in payments:
        if not isinstance(p, dict):
            continue
        pid = str(p.get('payment_id', ''))
        if pid.startswith('certificate_'):
            cert += 1
        elif pid.startswith('gift_card_'):
            gift += 1
        elif pid.startswith('credit_card_'):
            credit += 1
    if cert > 1 or gift > 3 or credit > 1:
        return True
    return False"
