{"checks":[{"name":"transfer_when_action_possible","code":"def check(call, history):
    if call.get('name') != 'transfer_to_human_agents':
        return False
    summary = str(call.get('arguments', {}).get('summary', '')).lower()
    statuses = []
    def walk(x):
        if isinstance(x, dict):
            if 'status' in x:
                statuses.append(str(x['status']).lower())
            for v in x.values():
                walk(v)
        elif isinstance(x, list):
            for v in x:
                walk(v)
    for msg in history:
        if msg.get('role') == 'tool':
            walk(msg.get('result'))
    flown = any(s in ('landed', 'flying') for s in statuses)
    if flown:
        return False

    change_words = ('change', 'modify', 'cancel', 'rebook', 'reroute', 'reschedule')
    has_change = any(w in summary for w in change_words)

    other_blockers = (
        'sold out', 'unavailable', 'not available', 'full', 'no seats',
        'payment', 'fund', 'balance', 'not enough', 'error', 'system',
        'failed', 'closed', 'expired', 'weather', 'delay', 'already',
        'not eligible', 'ineligible'
    )
    has_other_blocker = any(w in summary for w in other_blockers)

    if (('basic economy' in summary or 'basic_economy' in summary)
            and any(w in summary for w in ('upgrade', 'cabin', 'business class', 'business cabin'))
            and not has_change and not has_other_blocker):
        return True

    if 'upgrade' in summary and 'cancel' in summary:
        negatives = (
            'cannot', 'can not', 'not allowed', 'not possible',
            'unable', 'policy', 'restriction', 'restricted', 'will not',
            'does not', 'unfortunately', 'sorry', 'ineligible',
            'not eligible'
        )
        if not any(w in summary for w in negatives) and not has_other_blocker:
            return True

    if 'passenger' in summary and ('saved passenger' in summary or 'saved_passenger' in summary or 'profile' in summary) and ('book' in summary or 'booking' in summary):
        negatives = ('not saved', 'not in profile', 'no saved', 'does not exist', 'no passenger', 'not found', 'unavailable', 'sold out')
        if not any(w in summary for w in negatives):
            return True

    return False"}]}

{"checks": [{"name": "cancel_uncovered_reason", "code": "def check(call, history):
    if call.get('name') != 'cancel_reservation':
        return False
    args = call.get('arguments', {})
    if not isinstance(args, dict):
        args = {}
    rid = args.get('reservation_id') or args.get('reservationId') or args.get('id')
    if not rid:
        return False

    import json
    from datetime import datetime

    def find_res(obj, rid):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if str(k).lower() in ('reservation_id', 'reservationid', 'id') and str(v) == str(rid):
                    return obj
            for v in obj.values():
                if str(v) == str(rid):
                    keys = [str(k).lower() for k in obj.keys()]
                    if any(x in keys for x in ('cabin', 'created_at', 'travel_insurance', 'status', 'flight_status')):
                        return obj
            for v in obj.values():
                res = find_res(v, rid)
                if res is not None:
                    return res
        elif isinstance(obj, list):
            for v in obj:
                res = find_res(v, rid)
                if res is not None:
                    return res
        return None

    res = None
    for msg in reversed(history):
        if msg.get('role') == 'tool':
            result = msg.get('result')
            if isinstance(result, str):
                try:
                    result = json.loads(result)
                except Exception:
                    pass
            res = find_res(result, rid)
            if res is not None:
                break

    def find_value(obj, key_substrings):
        if isinstance(obj, dict):
            for k, v in obj.items():
                k_low = str(k).lower()
                if any(sub in k_low for sub in key_substrings):
                    return v
            for v in obj.values():
                val = find_value(v, key_substrings)
                if val is not None:
                    return val
        elif isinstance(obj, list):
            for v in obj:
                val = find_value(v, key_substrings)
                if val is not None:
                    return val
        return None

    def find_all_values(obj, key_substrings):
        vals = []
        if isinstance(obj, dict):
            for k, v in obj.items():
                k_low = str(k).lower()
                if any(sub in k_low for sub in key_substrings):
                    vals.append(v)
                vals.extend(find_all_values(v, key_substrings))
        elif isinstance(obj, list):
            for v in obj:
                vals.extend(find_all_values(v, key_substrings))
        return vals

    statuses = []
    if res is not None:
        raw_statuses = find_all_values(res, ['status'])
        for s in raw_statuses:
            if isinstance(s, str):
                statuses.append(s.lower())
            elif isinstance(s, dict):
                for v in s.values():
                    if isinstance(v, str):
                        statuses.append(v.lower())
    if not statuses:
        for msg in history:
            if msg.get('role') == 'tool':
                result = msg.get('result')
                if isinstance(result, str):
                    try:
                        result = json.loads(result)
                    except Exception:
                        pass
                raw = find_all_values(result, ['status'])
                for s in raw:
                    if isinstance(s, str):
                        statuses.append(s.lower())
                    elif isinstance(s, dict):
                        for v in s.values():
                            if isinstance(v, str):
                                statuses.append(v.lower())

    if any(s in ('landed', 'flying', 'in_air', 'departed') for s in statuses):
        return True
    if any(s == 'cancelled' for s in statuses):
        return False

    reason_text = None
    for k, v in args.items():
        k_low = str(k).lower()
        if any(sub in k_low for sub in ('reason', 'cause', 'explanation', 'note')):
            if isinstance(v, str):
                reason_text = v
                break
    if reason_text is None:
        for msg in reversed(history):
            if msg.get('role') == 'user':
                txt = str(msg.get('content', ''))
                txt_low = txt.lower()
                for pattern in ('because', 'due to', 'since', 'as', 'reason is', 'reason:'):
                    if pattern in txt_low:
                        idx = txt_low.find(pattern)
                        reason_text = txt[idx + len(pattern):].strip()
                        break
                if reason_text:
                    break
                covered_kw = ['health', 'weather', 'sick', 'illness', 'medical', 'emergency', 'doctor', 'hospital', 'injury', 'flu', 'covid', 'storm', 'hurricane', 'snow', 'rain', 'flood', 'natural disaster', 'bereavement', 'death', 'unwell']
                noncovered_kw = ['change of plan', 'other reason', 'mistake', 'mixup', 'booked by mistake', 'plans changed', 'schedule conflict', 'personal reason', 'moving', 'better deal', 'found cheaper', 'no longer need']
                if any(w in txt_low for w in covered_kw + noncovered_kw):
                    reason_text = txt
                    break
    if not reason_text:
        return False

    reason_low = reason_text.lower()
    covered_kw = ['health', 'weather', 'sick', 'illness', 'medical', 'emergency', 'doctor', 'hospital', 'injury', 'flu', 'covid', 'storm', 'hurricane', 'snow', 'rain', 'flood', 'natural disaster', 'bereavement', 'death', 'unwell']
    is_covered = any(w in reason_low for w in covered_kw)

    cabin = ''
    if res is not None:
        cab_val = find_value(res, ['cabin', 'cabin_class', 'fare_class', 'class'])
        if cab_val is not None:
            cabin = str(cab_val).lower()
    if 'business' in cabin:
        return False

    created_str = ''
    if res is not None:
        created_val = find_value(res, ['created', 'booked', 'creation', 'booking_date'])
        if created_val is not None:
            created_str = str(created_val)
    if created_str:
        dt = None
        for s in (created_str, created_str[:19]):
            for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%dT%H:%M:%S', '%Y-%m-%d %H:%M', '%Y-%m-%dT%H:%M', '%Y-%m-%d'):
                try:
                    dt = datetime.strptime(s, fmt)
                    break
                except Exception:
                    continue
            if dt is not None:
                break
        if dt is not None:
            start = datetime(2024, 5, 14, 15, 0, 0)
            end = datetime(2024, 5, 15, 15, 0, 0)
            if start <= dt <= end:
                return False

    has_ins = False
    if res is not None:
        ins_val = find_value(res, ['insurance', 'insured'])
        if ins_val is not None:
            if isinstance(ins_val, bool):
                has_ins = ins_val
            elif isinstance(ins_val, str):
                has_ins = ins_val.lower() in ('yes', 'true', '1', 'y')
            elif isinstance(ins_val, dict):
                def any_true(obj):
                    if isinstance(obj, dict):
                        return any(any_true(v) for v in obj.values())
                    elif isinstance(obj, list):
                        return any(any_true(v) for v in obj)
                    else:
                        return str(obj).lower() in ('yes', 'true', '1', 'y')
                has_ins = any_true(ins_val)
            elif isinstance(ins_val, (int, float)):
                has_ins = bool(ins_val)

    if is_covered and has_ins:
        return False

    return True
"}]}

