{"checks": [{"name": "price_rank_mismatch", "code": "def check(call, history):
    if call.get('name') not in ('book_reservation', 'update_reservation_flights'):
        return False
    recent_users = []
    for msg in reversed(history):
        if msg.get('role') == 'user':
            recent_users.append(str(msg.get('content', '')).lower())
            if len(recent_users) >= 2:
                break
    if not recent_users:
        return False
    latest_user = recent_users[0]
    text = ' '.join(recent_users)
    confirm_phrases = ['go ahead', 'book it', 'proceed', 'confirm', 'yes', 'okay', 'works', 'sounds good', 'do it', 'that works']
    if any(p in latest_user for p in confirm_phrases) and 'cheapest' not in latest_user and 'second cheapest' not in latest_user:
        return False
    if 'second cheapest' in text:
        rank = 1
    elif 'cheapest' in text and 'second' not in text:
        rank = 0
    else:
        return False
    if 'bag' in text or 'luggage' in text:
        return False
    args = call.get('arguments', {})
    cabin = args.get('cabin')
    if not cabin:
        return False
    flights = args.get('flights')
    if not isinstance(flights, list) or not flights:
        return False
    dates = set()
    for f in flights:
        if isinstance(f, dict) and f.get('date'):
            dates.add(f['date'])
    if len(dates) != 1:
        return False
    date = list(dates)[0]
    fmap = {}
    def walk(x):
        if isinstance(x, dict):
            fn = x.get('flight_number')
            if fn:
                prices = x.get('prices') or {}
                price = prices.get(cabin) if isinstance(prices, dict) else None
                if price is None:
                    price = x.get(cabin + '_price')
                if price is not None:
                    if fn not in fmap or price < fmap[fn]['price']:
                        fmap[fn] = {'origin': x.get('origin'), 'destination': x.get('destination'), 'price': price}
            for v in x.values():
                walk(v)
        elif isinstance(x, list):
            for v in x:
                walk(v)
    for msg in history:
        if msg.get('role') == 'tool':
            walk(msg.get('result'))
    origin = args.get('origin')
    destination = args.get('destination')
    if not origin or not destination:
        first_fn = flights[0].get('flight_number') if isinstance(flights[0], dict) else None
        last_fn = flights[-1].get('flight_number') if isinstance(flights[-1], dict) else None
        if first_fn in fmap:
            origin = fmap[first_fn]['origin']
        if last_fn in fmap:
            destination = fmap[last_fn]['destination']
    if not origin or not destination:
        return False
    selected = 0
    for f in flights:
        if not isinstance(f, dict):
            return False
        fn = f.get('flight_number')
        if fn not in fmap or fmap[fn]['price'] is None:
            return False
        selected += fmap[fn]['price']
    last_direct = None
    last_onestop = None
    pending = []
    for msg in history:
        if msg.get('role') == 'assistant' and msg.get('tool_calls'):
            for tc in msg['tool_calls']:
                pending.append(tc)
        elif msg.get('role') == 'tool':
            res = msg.get('result')
            if pending:
                tc = pending.pop(0)
                tname = tc.get('name')
                targs = tc.get('arguments', {})
                if targs.get('origin') == origin and targs.get('destination') == destination and targs.get('date') == date:
                    if tname == 'search_direct_flight':
                        last_direct = res
                    elif tname == 'search_onestop_flight':
                        last_onestop = res
    candidates = []
    if last_direct is not None and isinstance(last_direct, list):
        for item in last_direct:
            if isinstance(item, dict):
                prices = item.get('prices') or {}
                p = prices.get(cabin) if isinstance(prices, dict) else None
                if p is None:
                    p = item.get(cabin + '_price')
                if p is not None:
                    candidates.append(p)
    if last_onestop is not None and isinstance(last_onestop, list):
        for itinerary in last_onestop:
            if isinstance(itinerary, list):
                total = 0
                good = True
                for leg in itinerary:
                    if not isinstance(leg, dict):
                        good = False
                        break
                    prices = leg.get('prices') or {}
                    p = prices.get(cabin) if isinstance(prices, dict) else None
                    if p is None:
                        p = leg.get(cabin + '_price')
                    if p is None:
                        good = False
                        break
                    total += p
                if good:
                    candidates.append(total)
    if not candidates:
        return False
    candidates.sort()
    if rank >= len(candidates):
        return False
    return selected > candidates[rank]"}]}

{"checks": [{"name": "update_flights_wrong_destination", "code": "def check(call, history):
    if call.get('name') != 'update_reservation_flights':
        return False
    args = call.get('arguments', {})
    rid = args.get('reservation_id')
    if not rid:
        return False

    def walk(x):
        if isinstance(x, dict):
            yield x
            for v in x.values():
                yield from walk(v)
        elif isinstance(x, list):
            for v in x:
                yield from walk(v)

    res = None
    for msg in reversed(history):
        if msg.get('role') == 'tool':
            r = msg.get('result')
            if isinstance(r, (dict, list)):
                for d in walk(r):
                    if isinstance(d, dict) and d.get('reservation_id') == rid:
                        res = d
                        break
            if res:
                break
    if not res:
        return False

    orig_org = res.get('origin')
    orig_dst = res.get('destination')
    if not orig_dst and isinstance(res.get('flights'), list) and res['flights']:
        flights = res['flights']
        if isinstance(flights[0], dict):
            orig_org = orig_org or flights[0].get('origin')
            orig_dst = flights[-1].get('destination')
    if not orig_dst:
        return False

    texts = []
    for msg in reversed(history):
        if msg.get('role') == 'user':
            texts.append(str(msg.get('content', '')))
            if len(texts) >= 5:
                break
    text = ' '.join(texts)
    import re
    codes = set()
    for m in re.finditer(r'\b(?:to|want|need|prefer|go to|instead of|change to|switch to|fly to|flying to|going to)\s+([A-Za-z]{3})\b', text, re.IGNORECASE):
        codes.add(m.group(1).upper())
    for m in re.finditer(r'\b([A-Za-z]{3})\s+instead of\b', text, re.IGNORECASE):
        codes.add(m.group(1).upper())
    for m in re.finditer(r'\b([A-Za-z]{3})\s+is really\b', text, re.IGNORECASE):
        codes.add(m.group(1).upper())
    if not codes:
        return False

    fmap = {}
    for msg in history:
        if msg.get('role') == 'tool':
            r = msg.get('result')
            if isinstance(r, (dict, list)):
                for d in walk(r):
                    if isinstance(d, dict):
                        fn = d.get('flight_number')
                        dest = d.get('destination')
                        if fn and dest:
                            fmap[fn] = dest
    call_dests = set()
    flights_arg = args.get('flights', [])
    if isinstance(flights_arg, list):
        for f in flights_arg:
            fn = None
            dest = None
            if isinstance(f, dict):
                fn = f.get('flight_number')
                dest = f.get('destination')
            elif isinstance(f, str):
                fn = f
            if dest:
                call_dests.add(dest)
            elif fn in fmap:
                call_dests.add(fmap[fn])
    for c in codes:
        if c != orig_dst and c != orig_org and c not in call_dests:
            return True
    return False
"}]}

