        return True
    else:
        if '2024-05-15' in s:
            return False
        if '2024-05-14' in s:
            return False
        return True"},{"name":"book_reservation_flight_direction","description":"Stop booking calls whose flight numbers contradict the requested origin/destination direction.","clause":"Book flight requires the correct origin, destination, and trip type; flights must match the requested itinerary.","code":"def check(call, history):
    if call.get('name') != 'book_reservation':
