            if d != origin:
                return True
        else:
            if d != destination:
                return True
    return False"},{"name":"send_certificate_requires_change_or_cancel","description":"Stop delayed-flight compensation when the user has not changed/cancelled and has even declined to do so.","clause":"For delayed-flight complaints, compensation may be offered only when the user wants to change or cancel the reservation and after the change or cancellation is performed.","code":"def check(call, history):
