                    changed = True
    if not changed:
        return True
    return False"},{"name":"update_baggages_requires_explicit_extra_bag_request","description":"Stop baggage updates that charge for nonfree bags unless the user explicitly requested a specific number of extra/paid bags.","clause":"Do not add checked bags that the user does not need; extra baggage is charged only for requested additional bags.","code":"def check(call, history):
