{"checks":[{"name":"payment_method_in_profile","code":"def check(call, history):
    name = call.get('name')
    if name not in ('update_reservation_flights', 'update_reservation_baggages', 'book_reservation'):
        return False
    args = call.get('arguments', {})
    if isinstance(args, str):
        try:
            import json
            args = json.loads(args)
        except Exception:
            args = {}
    if not isinstance(args, dict):
        args = {}
    pids = []
    def add_pid(value):
        if isinstance(value, str) and value:
            pids.append(value)
        elif isinstance(value, dict):
            pid = value.get('payment_id') or value.get('id')
            if isinstance(pid, str) and pid:
                pids.append(pid)
            else:
                for k, v in value.items():
                    if isinstance(k, str) and k:
                        pids.append(k)
                    add_pid(v)
        elif isinstance(value, list):
            for item in value:
                add_pid(item)
    if args.get('payment_id'):
        add_pid(args['payment_id'])
    if name == 'book_reservation':
        add_pid(args.get('payment_methods', []))
    if not pids:
        return False
    profile_pids = set()
    def add_profile_pid(value):
        if isinstance(value, str) and value:
            profile_pids.add(value)
        elif isinstance(value, dict):
            pid = value.get('payment_id') or value.get('id')
            if isinstance(pid, str) and pid:
                profile_pids.add(pid)
            else:
                for k, v in value.items():
                    if isinstance(k, str) and k:
                        profile_pids.add(k)
                    add_profile_pid(v)
        elif isinstance(value, list):
            for item in value:
                add_profile_pid(item)
    def extract(obj):
        if isinstance(obj, dict):
            if 'payment_methods' in obj:
                add_profile_pid(obj['payment_methods'])
            for v in obj.values():
                extract(v)
        elif isinstance(obj, list):
            for item in obj:
                extract(item)
        elif isinstance(obj, str):
            s = obj.strip()
            if s.startswith('{') or s.startswith('['):
                try:
                    import json
                    extract(json.loads(s))
                except Exception:
                    pass
    for msg in history:
        if not isinstance(msg, dict):
            continue
        role = msg.get('role')
        if role == 'tool' or 'result' in msg or 'tool_response' in msg:
            if 'result' in msg:
                extract(msg['result'])
            if 'content' in msg:
                extract(msg['content'])
            if 'tool_response' in msg:
                extract(msg['tool_response'])
            if role == 'tool':
                extract(msg)
    if not profile_pids:
        return False
    for pid in pids:
        if pid not in profile_pids:
            return True
    return False"}]}

