{"checks":[{"name":"transfer_for_policy_exception_or_verification","description":"Flags transfers to human agents only when the transfer summary or explicit user request indicates a policy exception/waiver/override or policy/eligibility verification, avoiding generic supervisor/escalation mentions.","code":"def check(call, history):
    if call.get('name') != 'transfer_to_human_agents':
        return False

    args = call.get('arguments', {}) or {}
    summary = str(args.get('summary', '')).lower()

